/**
 * SUNLOC INTEGRATED SERVER v2
 * Stack: PostgreSQL (production) or SQLite (local dev)
 * Set DATABASE_URL env var to use PostgreSQL automatically.
 * All 107 db.prepare().get/run/all() calls work unchanged via the adapter.
 */

'use strict';

const express = require('express');
const cors    = require('cors');
const path    = require('path');
const fs      = require('fs');

// v46C: SINGLE source of truth for the build version. /api/health and the SAP serverBuild responses
// all read this — so the reported version can never again drift from the deployed code (the v46B
// deploy confusion was a stale hardcoded 'v45ZV' health stamp masquerading as a failed deploy). A
// validator check (sunloc_validate.py) fails the build if this does not match the HTML build markers.
const APP_BUILD = 'v57A';
// ═══ v53K item 1 — FUTURE-TS CLAMP (re-applied; first shipped in v53I, dropped when v53J was forked ═
// from v53H in a parallel chat and deployed over it) ══════════════════════════════════════════════
// 68 real AIM scans arrived stamped 2036 because the scan routes store the CLIENT's ts verbatim and
// one station's clock was ten years ahead (NTP-era wraparound signature). Any device ts more than
// 48h ahead of server time is stored as server time with a log line; recon signatures (label
// 'recon-%', operator 'recon:%' / 'recon-scrap:%') are exempt — their month-window-end future ts is
// by design. Past-dated ts (offline replays) and unparseable ts pass through untouched.
const _V53K_FUTURE_MS = 48 * 3600 * 1000;
function _v53kClampTs(scan, route) {
  try {
    const ts = scan && scan.ts;
    if (!ts) return ts;
    const lid = String(scan.labelId || scan.label_id || ''), op = String(scan.operator || '');
    if (lid.startsWith('recon-') || op.startsWith('recon:') || op.startsWith('recon-scrap:')) return ts;
    const t = Date.parse(ts);
    if (!Number.isFinite(t)) return ts;
    const now = Date.now();
    if (t - now <= _V53K_FUTURE_MS) return ts;
    const fixed = new Date(now).toISOString();
    console.warn(`[v53K ts-clamp] ${route} ${scan.dept}:${scan.type} batch ${scan.batchNumber || scan.batch_number || '?'} device ts ${ts} → ${fixed}`);
    return fixed;
  } catch (e) { return scan && scan.ts; }
}
// v51M BUILD FINGERPRINT (my own process failure, 9 Aug): two DIFFERENT v51L archives were shipped
// — one before the Truck/Order scope unification and one after — and both reported build 'v51L' on
// /api/health, so there was no way to tell from the running server which one was actually deployed.
// A short hash of server.js + the three HTML apps is computed at boot and returned alongside the
// build letter: two archives that differ in any byte now report different fingerprints, and the
// letter alone is never again the only evidence of what is running.
const BUILD_FINGERPRINT = (() => {
  try {
    const _c = require('crypto'), _f = require('fs'), _p = require('path');
    const h = _c.createHash('sha256');
    for (const rel of ['server.js', 'public/planning.html', 'public/dpr.html', 'public/tracking.html',
                       'assistant-engine.js', 'public/assistant.html', 'public/sunloc-core.js',
                       'public/gpr.html']) {   // v52: assistant files are load-bearing; v55: gpr.html joins the GPR merge
      try { h.update(_f.readFileSync(_p.join(__dirname, rel))); } catch (_) { h.update('missing:' + rel); }
    }
    return h.digest('hex').slice(0, 12);
  } catch (e) { return 'unavailable'; }
})();
// ═══ v50T WRITE AUDIT (5 Aug — the definitive tracer for the ZA078/ZA079 flip saga) ══════════════
// Every server path that can change a watched batch's planner fields calls _v50tAudit before
// writing. One amendment then produces a complete, ordered trace in the Railway logs: which route
// wrote, what changed, the client's edit stamp and build, and whether a claim list was present —
// no more archaeology. Watchlist via env SUNLOC_AUDIT_BATCHES (comma-separated), default the two
// batches under investigation. Cheap: string compare + one log line, only for watched batches.
const _v50tWatch = new Set(String(process.env.SUNLOC_AUDIT_BATCHES || '26ZA078,26ZA079').split(',').map(s => s.trim().toUpperCase()).filter(Boolean));
function _v50tAudit(route, before, after, extra) {
  try {
    const bn = String((after && after.batchNumber) || (before && before.batchNumber) || '').trim().toUpperCase();
    if (!bn || !_v50tWatch.has(bn)) return;
    const FIELDS = ['startDate', 'endDate', 'batchNumber', 'machineId', 'status', 'manualStartDate', 'manualEndDate', 'grossOverride'];
    const diffs = [];
    for (const k of FIELDS) {
      const a = before ? before[k] : undefined, b = after ? after[k] : undefined;
      if (JSON.stringify(a === undefined ? null : a) !== JSON.stringify(b === undefined ? null : b)) diffs.push(`${k}: ${JSON.stringify(a)} → ${JSON.stringify(b)}`);
    }
    if (!diffs.length) return;
    console.log(`[v50T AUDIT] ${bn} via ${route} | stamp=${(after && after._localEditedAt) || (before && before._localEditedAt) || '-'} | ${diffs.join(' ; ')}${extra ? ' | ' + extra : ''}`);
  } catch (e) { /* audit must never break a write */ }
}

// ═══ v53L (Rahul, 02 Sep — "DPR save not syncing / close a batch → slow → hang") ══════════════════
// One multi-row upsert for production_actuals, chunked (same v41w pattern as production_orders).
// Replaces three serial INSERT-per-run loops: the save route's main write, its v43 #1 restore pass,
// and the batch-close flush. Identical ON CONFLICT semantics at every site (order/batch/qty win,
// synced_at bumped). rows = [order_id, batch_number, machine_id, date, shift, run_index, qty, floor].
async function _v53lUpsertActuals(rows, client) {
  if (!rows || !rows.length) return 0;
  const q = client || pgPool;
  const CHUNK = 100;
  let n = 0;
  for (let i = 0; i < rows.length; i += CHUNK) {
    const chunk = rows.slice(i, i + CHUNK);
    const vals = [], params = [];
    chunk.forEach((r, k) => {
      const b = k * 8;
      vals.push(`($${b+1},$${b+2},$${b+3},$${b+4},$${b+5},$${b+6},$${b+7},$${b+8})`);
      params.push(r[0] == null ? null : r[0], r[1] == null ? null : r[1], r[2], r[3], r[4], r[5], r[6], r[7] == null ? null : r[7]);
    });
    await q.query(
      `INSERT INTO production_actuals (order_id, batch_number, machine_id, date, shift, run_index, qty_lakhs, floor)
       VALUES ${vals.join(',')}
       ON CONFLICT(machine_id, date, shift, run_index) DO UPDATE SET
         order_id=EXCLUDED.order_id, batch_number=EXCLUDED.batch_number,
         qty_lakhs=EXCLUDED.qty_lakhs, synced_at=NOW()`, params);
    n += chunk.length;
  }
  return n;
}

// ═══ v53P — LEGACY RE-BATCH (Ishan, 03 Sep 2026) ═════════════════════════════════════════════════════
// Stock produced before Sunloc (2025, white labels) is re-batched into a current batch and shipped
// under it with fresh blue labels. Those labels are the R-series: tracking_labels rows with
// is_legacy_rebatch=1, legacy_ref = the old batch, legacy_num = 1..n, and label_number =
// -(_V53P_R_BASE + n) so no positive-number path (normal 1..N) or excess path (E-n) can ever claim
// them. They exist on the dispatch side only: Packing IN → Dispatch OUT, dispatch records, truck,
// SAP delivery and invoice allocation all see them; production-side sums (WIP, A-grade, packed,
// Reports B/D/E/G/H production legs, month-end) never do — the scan-summary routes their scans into
// legacy* fields. rebatch_log is the ledger (one row per re-batch action).
const _V53P_R_BASE = 100000;
// v53Q (Ishan, 03 Sep): orange twins of R-labels (printed target batch) live in their own range so they
// can never collide with routine oranges (1,000,000+n) or excess oranges (1,500,000+n).
const _ORANGE_LEGACY_NUM_BASE = 2000000;
function _v53pBoxLabel(num, isExcess, excessNum, isLegacy, legacyNum) {
  const n = Number(num) || 0;
  if (Number(isLegacy) === 1 || n <= -_V53P_R_BASE || n >= _ORANGE_LEGACY_NUM_BASE) return 'R-' + (legacyNum || (n >= _ORANGE_LEGACY_NUM_BASE ? n - _ORANGE_LEGACY_NUM_BASE : Math.abs(n) - _V53P_R_BASE));
  if (Number(isExcess) === 1 || n < 0) return 'E-' + (excessNum || Math.abs(n));
  return String(Math.abs(n));
}
async function _v53pEnsureRebatchLog() {
  const ddl = `CREATE TABLE IF NOT EXISTS rebatch_log (
    id TEXT PRIMARY KEY, ts TEXT NOT NULL, by_user TEXT, legacy_ref TEXT NOT NULL, target_batch TEXT NOT NULL,
    qty_lakhs REAL NOT NULL, boxes INTEGER NOT NULL, size TEXT, label_ids TEXT, note TEXT, orange_ids TEXT, mode TEXT, details_json TEXT)`;
  if (pgPool) { await pgPool.query(ddl); for (const col of ['orange_ids TEXT','mode TEXT','details_json TEXT']) await pgPool.query(`ALTER TABLE rebatch_log ADD COLUMN IF NOT EXISTS ${col}`).catch(()=>{}); }
  else { db.exec(ddl); for (const col of ['orange_ids TEXT','mode TEXT','details_json TEXT']) { try { db.exec(`ALTER TABLE rebatch_log ADD COLUMN ${col}`); } catch (_) {} } }
}

// v53U (Ishan, 03 Sep): standalone legacy batches have no DPR actuals and no order start date, so
// both production-month attributions (generated-invoices prod_month filter, Over-invoiced month
// filter) fall through to the admin-entered mfg month from the re-batch ledger. Third tier only —
// never overrides a real production date.
async function _v53uLegacyMonths(bns) {
  const out = {};
  try {
    const keys = (bns || []).map(b => String(b).trim().toUpperCase()).filter(Boolean);
    if (!keys.length) return out;
    const rows = pgPool
      ? (await pgPool.query(`SELECT UPPER(TRIM(target_batch)) AS bn, details_json FROM rebatch_log WHERE COALESCE(mode,'merge')='standalone' AND UPPER(TRIM(target_batch)) = ANY($1) ORDER BY ts ASC`, [keys])).rows
      : db.prepare(`SELECT UPPER(TRIM(target_batch)) AS bn, details_json FROM rebatch_log WHERE COALESCE(mode,'merge')='standalone' AND UPPER(TRIM(target_batch)) IN (${keys.map(()=>'?').join(',')}) ORDER BY ts ASC`).all(...keys);
    for (const r of rows) { try { const d = JSON.parse(r.details_json || '{}'); if (d.mfg && /^\d{4}-\d{2}$/.test(d.mfg) && !out[r.bn]) out[r.bn] = d.mfg; } catch (_) {} }
  } catch (e) { console.warn('[v53U legacy months]', e.message); }
  return out;
}

// ═══ v53K item 2 — UP→PTD CONVERSION GUARD on the planning write paths (Ishan, 01 Sep) ══════════════
// 26N045 / 26N047 were planned unprinted, scanned AIM→Packing (12.45L + 17.05L packed as UP FG), then
// Planning_Manager flipped isPrinted on the ORDER EDIT FORM (31 Aug 06:03–06:05 UTC, ORDER_EDITED). Only
// the Re-customer CONVERT endpoint carried the v44C D5 reversal step, so the pack-in scans survived and
// the same 29.50L sat in FG UP *and* in the AIM→Printing handover gap at once. Rule (Ishan): on an
// unprinted→printed conversion the FG must be reversed — the stock shows only as WIP and re-flows
// Printing→PI→Packing. This guard runs as a pre-pass on BOTH order write paths (blob merge and
// upsert-bulk) so the flip cannot arrive by any route without its reversal:
//   • flip detected  = incoming isPrinted === true while the stored copy was not printed;
//   • already dispatched (either flow) → the flip is REFUSED (same rule as Re-customer CONVERT): the
//     incoming order's isPrinted is reverted to false, audited, and reported to the client;
//   • otherwise every live packing scan gets a ledger reversal row (identical INSERT to D5 — originals
//     preserved, idempotent by id), audited, and reported so the planner sees what moved.
// Never blocks a save: any failure logs and lets the write proceed exactly as before.
async function _v53kConvertGuard(prevOf, orders, who, route) {
  const notices = [];
  if (!Array.isArray(orders)) return notices;
  for (const o of orders) {
    try {
      if (!o || !o.id || o.deleted || o.isPrinted !== true) continue;
      const prev = prevOf(o);
      if (!prev || prev.isPrinted === true) continue;                 // not a false→true flip
      const bn = String(o.batchNumber || prev.batchNumber || '').trim();
      if (!bn) continue;
      let dispatched = false;
      if (pgPool) {
        const r = await pgPool.query(`SELECT (EXISTS (SELECT 1 FROM tracking_scans WHERE UPPER(batch_number)=UPPER($1) AND dept='dispatch') OR EXISTS (SELECT 1 FROM tracking_dispatch_records WHERE UPPER(batch_number)=UPPER($1))) AS d`, [bn]);
        dispatched = !!(r.rows[0] && r.rows[0].d);
      } else {
        dispatched = !!db.prepare(`SELECT 1 FROM tracking_scans WHERE UPPER(batch_number)=UPPER(?) AND dept='dispatch' LIMIT 1`).get(bn);
      }
      if (dispatched) {
        o.isPrinted = false;
        try { logAudit(who, 'planning', 'planning', 'UP_TO_PTD_REFUSED', `${bn}: unprinted→printed refused via ${route} — box(es) already dispatched. Re-customer without conversion, or handle dispatch first.`); } catch (_) {}
        notices.push({ id: o.id, batchNumber: bn, refused: true, reason: 'already dispatched' });
        continue;
      }
      const ts = new Date().toISOString();
      const reason = `Planning UP→PTD conversion via ${route} (${who}) — pack-in reversed; box re-flows Printing→PI→Packing`;
      let n = 0;
      if (pgPool) {
        const r = await pgPool.query(`INSERT INTO tracking_scan_reversals (id, reversed_scan_id, batch_number, label_id, dept, type, reason, by_user, ts) SELECT 'rev-'||s.id, s.id, s.batch_number, s.label_id, s.dept, s.type, $2, $3, $4 FROM tracking_scans s WHERE UPPER(s.batch_number)=UPPER($1) AND s.dept='packing' AND NOT EXISTS (SELECT 1 FROM tracking_scan_reversals r WHERE r.reversed_scan_id=s.id)`, [bn, reason, who, ts]);
        n = r.rowCount || 0;
      } else {
        const r = db.prepare(`INSERT OR IGNORE INTO tracking_scan_reversals (id, reversed_scan_id, batch_number, label_id, dept, type, reason, by_user, ts) SELECT 'rev-'||s.id, s.id, s.batch_number, s.label_id, s.dept, s.type, ?, ?, ? FROM tracking_scans s WHERE UPPER(s.batch_number)=UPPER(?) AND s.dept='packing'`).run(reason, who, ts, bn);
        n = r.changes || 0;
      }
      try { logAudit(who, 'planning', 'planning', 'UP_TO_PTD_CONVERT', `${bn}: unprinted→printed via ${route} — ${n} packing scan(s) reversed (ledger), stock returns to WIP pending Printing scan-in`); } catch (_) {}
      notices.push({ id: o.id, batchNumber: bn, reversed: n });
    } catch (e) { console.warn(`[v53K convert-guard] ${route} skipped for ${(o && o.batchNumber) || '?'}:`, e && e.message); }
  }
  if (notices.length) console.log(`[v53K convert-guard] ${route} (${who}): ` + notices.map(x => x.refused ? `${x.batchNumber} REFUSED (${x.reason})` : `${x.batchNumber} ${x.reversed} pack-in reversed`).join('; '));
  return notices;
}

// v47G (confirmed by Ishan): authoritative per-box scan quantity in SQL. Every scanned REAL box is
// valued at its label's actual qty (tracking_labels.qty — partial-aware, the NOT-NULL source of
// truth), NOT box-count × a uniform pack size. Recon-synthetic scans (label_id 'recon-%', no real
// label) keep their own stored Lakhs (s.qty). A real box with no matching label falls back to the
// pack-standard size for its size code (the agreed fallback), using the canonical pack map that
// mirrors the client PACK_SIZES. Used by scan-summary, agrade-summary and agrade-by-month so that
// Scan-In / Scan-Out — and the Inspected / A-Grade / WIP legs derived from them — are the true
// summed quantity across every report and plan. `s` = tracking_scans alias, `l` = tracking_labels.
function _v47gPackCaseSql(s) {
  return `CASE ${s}.size WHEN '00' THEN 0.75 WHEN '0' THEN 1.00 WHEN '1' THEN 1.25 `
       + `WHEN '2' THEN 1.75 WHEN '3' THEN 2.25 WHEN '4' THEN 3.00 ELSE 0 END`;
}
// v50X (confirmed by Ishan): scrap-disposition per-box recon outs (operator 'recon-scrap:%') are
// valued at ZERO here. They exist only to clear the physical box from every WIP box set / box count
// (in==out coherence) after a Report Z dept reconcile writes the loss off as wastage — the wastage
// row is the sole quantity record, so letting the label's qty flow here would double-count the loss
// AND wrongly inflate AIMOut (A-Grade numerator). Movepack per-box outs carry operator 'recon:%'
// with qty NULL and deliberately fall through to the label-qty branch — packed-good output is real
// output. Single authority: scan-summary, agrade-summary, agrade-by-month and dispatch-period all
// inherit this uniformly.
// v54C (Rahul, 10 Sep — "pre-AIM unscanned WIP jumps when PI regenerates the last label with a smaller
// qty"): regeneratePartialLabel voids the old label, issues a new one with the REDUCED qty and repoints
// every scan of that box onto it (v49J). Valuing scans at the label's CURRENT qty therefore shrank the
// box's AIM scan-in retroactively, and pre-AIM (gross − salvage − AIM in) rose by the difference — the
// removed quantity was already recorded as printing/PI salvage, so it was being counted twice. A scan
// is now valued at the qty in force WHEN IT WAS SCANNED: scans stamped before regenerated_at use
// original_qty (the voided label's qty); later scans (PI out, packing, dispatch) use the new qty.
// Stage-agnostic — a regeneration at Packing behaves the same way. Lineage is written by the
// relabel-repoint route; the "SQL for IT" backfill sets it for regenerations made before v54C.
function _v47gScanQtySql(s, l) {
  return `CASE WHEN ${s}.operator LIKE 'recon-scrap:%' THEN 0 `
       + `WHEN ${s}.label_id LIKE 'recon-%' THEN COALESCE(${s}.qty,0) `
       + `WHEN ${l}.original_qty IS NOT NULL AND ${l}.regenerated_at IS NOT NULL AND ${s}.ts < ${l}.regenerated_at THEN ${l}.original_qty `
       + `ELSE COALESCE(${l}.qty, ${_v47gPackCaseSql(s)}) END`;
}


// ── v44Y: PC Master fallback resolver ──────────────────────────────────────────
// Invoice enrichment derives size/colour from an ItemCode. The server `pc_codes`
// table (admin-saved + hand-edited + future PC-Master additions) is the authoritative
// source and is queried FIRST (it wins). This map is the comprehensive shipped master
// (public/pc-codes-data.js → PC_CODES_RAW), used only as a FALLBACK so a code that was
// never saved server-side still resolves its size/colour. Loaded once and cached; a new
// deploy of pc-codes-data.js refreshes it automatically on next startup.
let _pcMasterMap = null;
function _getPcMasterMap() {
  if (_pcMasterMap) return _pcMasterMap;
  _pcMasterMap = new Map();
  try {
    const txt = fs.readFileSync(path.join(__dirname, 'public', 'pc-codes-data.js'), 'utf8');
    const start = txt.indexOf('{');
    const end = txt.lastIndexOf('}');
    if (start >= 0 && end > start) {
      const raw = JSON.parse(txt.slice(start, end + 1));
      for (const sz of Object.keys(raw)) {
        const list = raw[sz] || [];
        for (const e of list) {
          if (!e || !e.c) continue;
          const code = String(e.c).trim();
          if (code && !_pcMasterMap.has(code)) _pcMasterMap.set(code, { size: sz, colour: e.n || '' });
        }
      }
    }
    console.log('[PC master] loaded ' + _pcMasterMap.size + ' codes from pc-codes-data.js (enrichment fallback)');
  } catch (e) {
    console.warn('[PC master] could not load pc-codes-data.js fallback:', e.message);
  }
  return _pcMasterMap;
}
function _pcMasterLookup(code) {
  if (!code) return null;
  return _getPcMasterMap().get(String(code).trim()) || null;
}
const crypto  = require('crypto');

// v39: SAP B1 Service Layer client — handles login, session, audit, graceful degradation
const { SapClient } = require('./sap-client');

const app  = express();
const PORT = process.env.PORT || 3000;

app.use(cors());
app.use(express.json({ limit: '10mb' }));
// ═══ v50T HTML CACHE KILL (5 Aug — Railway logs prove a pre-v48Z planning.html STILL live on the
// floor: "[v50L] list-less save (legacy/stale client)" fired twice in a 5-minute window). With
// Cloudflare fronting the domain and express.static's default caching, deployed HTML does not
// reliably reach browsers — a permanently MIXED-VERSION fleet, which is why every fix "held on one
// machine and not another" throughout the ZA078/ZA079 saga. App shells are now no-store (browsers
// AND the CDN must revalidate every load); static assets keep normal caching.
app.use((req, res, next) => {
  const p = (req.path || '').toLowerCase();
  if (p === '/' || p.endsWith('.html')) {
    res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate');
    res.setHeader('Pragma', 'no-cache');
    res.setHeader('Expires', '0');
  }
  // v52J (Ishan, 21 Aug — pack-size "revert overnight"): APIs join the no-store rule. API GET
  // responses carried NO Cache-Control at all, and this domain's edge cache demonstrably caches
  // extension-less/HTML responses when unhinted (the /assistant.html 4th-card incident needed a
  // manual purge). A cached GET /api/pack-sizes shows yesterday's values on this morning's load
  // even though the explicit POST persisted — indistinguishable on screen from a real revert.
  // Live data must never be served by the CDN: every /api response is now explicitly no-store.
  // (The jsqr.min.js static asset keeps its own public,max-age header — it is not under /api.)
  else if (p.startsWith('/api/')) {
    res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate');
    res.setHeader('Pragma', 'no-cache');
  }
  next();
});
app.use(express.static(path.join(__dirname, 'public')));

// ─── Database — Dual Mode ──────────────────────────────────────
// When DATABASE_URL is set: uses PostgreSQL via db-pg-sync.js adapter
// (same synchronous db.prepare().get/run/all() API as better-sqlite3)
// When not set: uses better-sqlite3 directly (local dev / Railway SQLite)

let db;
const USE_POSTGRES = !!process.env.DATABASE_URL;

// ── Legacy order cutoff: orders with startDate on or before this date
//    are treated as legacy (already in plant) and exempt from 2-order limit
const LEGACY_CUTOFF = '2026-04-19';

let DB_PATH = 'postgres'; // overwritten below in SQLite mode; must be top-level so health endpoint never throws ReferenceError

if (USE_POSTGRES) {
  const { PgDatabase } = require('./db-pg-sync');
  db = new PgDatabase();
  console.log('[DB] Mode: PostgreSQL');
}

// Direct async pg pool for large queries
let pgPool = null;
if (USE_POSTGRES) {
  try {
    const { Pool } = require('pg');
    pgPool = new Pool({ connectionString: process.env.DATABASE_URL, ssl: { rejectUnauthorized: false }, max: 10, keepAlive: true, idleTimeoutMillis: 30000, connectionTimeoutMillis: 10000 });
    // v44F: a cloud Postgres dropping an IDLE pooled connection emits a pool 'error'. With NO listener,
    // node-postgres rethrows it as an uncaught exception and the ENTIRE process crashes — which silently
    // stops all scan saves (clients then queue scans locally and retry every 10s). Handle it so a routine
    // idle drop never crashes the server. keepAlive + idle/connect timeouts reduce idle-drop churn and
    // stop a single slow/stuck connection from blocking saves. (max 5 -> 10 for multi-device sync load.)
    pgPool.on('error', (err) => { console.error('[DB] idle pg client error (handled — NOT crashing):', err && err.message); });
    console.log('[DB] Direct pg pool ready (max=10, keepAlive, idle/connect timeouts, error-handled)');
  } catch(e) { console.error('[DB] pg pool error:', e.message); }
} else {
  const Database = require('better-sqlite3');

  function resolveDbPath() {
    if (process.env.DB_PATH) return process.env.DB_PATH;
    const volumePath = '/data/sunloc.db';
    try {
      const dir = '/data';
      if (!fs.existsSync(dir)) fs.mkdirSync(dir, { recursive: true });
      fs.accessSync(dir, fs.constants.W_OK);
      console.log('[DB] Using persistent volume: ' + volumePath);
      return volumePath;
    } catch (e) {
      const localPath = path.join(__dirname, 'sunloc.db');
      console.log('[DB] Volume not available, using local: ' + localPath);
      return localPath;
    }
  }

  DB_PATH = resolveDbPath();
  db = new Database(DB_PATH);
  db.pragma('journal_mode = WAL');
  db.pragma('foreign_keys = ON');
  console.log('[DB] Mode: SQLite at ' + DB_PATH);
}

// ─── v39: SAP Client singleton ─────────────────────────────────
// One SapClient instance per process, shared across all endpoints.
// In PG mode it uses pgPool for the async DB calls; in SQLite mode
// it uses the same `db` better-sqlite3 instance. SAP_ENCRYPT_KEY env
// var must be set on Railway before configuring SAP credentials.
