async function _gprUpgradeMastersV55V() {
  const get1 = async (key) => {
    const sql = `SELECT value_json FROM gpr_masters WHERE master_key=${pgPool ? '$1' : '?'}`;
    const r = pgPool ? (await pgPool.query(sql, [key])).rows[0] : db.prepare(sql).get(key);
    return r ? JSON.parse(r.value_json) : null;
  };
  const put1 = async (key, val) => {
    if (pgPool) await pgPool.query(`INSERT INTO gpr_masters (master_key, value_json, updated_by) VALUES ($1,$2,'v55V-seed')
      ON CONFLICT(master_key) DO UPDATE SET value_json=$2, updated_by='v55V-seed', updated_at=NOW()::TEXT`, [key, JSON.stringify(val)]);
    else db.prepare(`INSERT INTO gpr_masters (master_key, value_json, updated_by) VALUES (?,?,'v55V-seed')
      ON CONFLICT(master_key) DO UPDATE SET value_json=excluded.value_json, updated_by='v55V-seed', updated_at=datetime('now')`).run(key, JSON.stringify(val));
  };
  try {
    // v55W (Ishan's point 1): the map lives in gpr_pc_colour_map (Planning's pc_codes pattern),
    // NOT in the masters blob — seed the table once, and self-heal any v55V-era blob copies away
    // so /api/gpr/masters stays light on every app load. The datalists derive from the table.
    const nSql = `SELECT COUNT(*) AS n FROM gpr_pc_colour_map`;
    const nRow = pgPool ? (await pgPool.query(nSql)).rows[0] : db.prepare(nSql).get();
    if (Number((nRow && nRow.n) || 0) === 0) {
      if (pgPool) {
        for (let k = 0; k < GPR_PC_COLOUR_TUPLES.length; k += 500) {
          const chunk = GPR_PC_COLOUR_TUPLES.slice(k, k + 500);
          const vals = []; const params = [];
          chunk.forEach((t, j) => { const b = j * 5; vals.push(`($${b+1},$${b+2},$${b+3},$${b+4},$${b+5},'v55W-seed')`); params.push(t[0], t[1], t[2], t[3], t[4]); });
          await pgPool.query(`INSERT INTO gpr_pc_colour_map (pc,size,name,cap_code,body_code,updated_by) VALUES ${vals.join(',')} ON CONFLICT(pc) DO NOTHING`, params);
        }
      } else {
        const ins = db.prepare(`INSERT OR IGNORE INTO gpr_pc_colour_map (pc,size,name,cap_code,body_code,updated_by) VALUES (?,?,?,?,?,'v55W-seed')`);
        for (const t of GPR_PC_COLOUR_TUPLES) ins.run(t[0], t[1], t[2], t[3], t[4]);
      }
      console.log(`[v55W GPR] gpr_pc_colour_map seeded — ${GPR_PC_COLOUR_TUPLES.length} product codes`);
    }
    // shrink v55V-era blob copies if a v55V boot ever ran (self-heal, logged)
    const del1 = async (key) => {
      const dSql = `DELETE FROM gpr_masters WHERE master_key=${pgPool ? '$1' : '?'}`;
      if (pgPool) await pgPool.query(dSql, [key]); else db.prepare(dSql).run(key);
    };
    if (await get1('pc_colour_map')) { await del1('pc_colour_map'); console.log('[v55W GPR] pc_colour_map blob removed from masters (table is authoritative)'); }
    const ccs = await get1('cutting_colour_codes');
    if (Array.isArray(ccs) && ccs.length >= 2000) { await put1('cutting_colour_codes', []); console.log('[v55W GPR] bulk colour-code blob reset — datalists derive from the PC table'); }
    else if (!Array.isArray(ccs)) { await put1('cutting_colour_codes', []); }
    // Legacy cutting stock opening seed (Shri Kant Gupta, 19 Sep 2026) — one-time, same guard as
    // the /api/gpr/legacy/import route: never re-seeds if ANY legacy_seed row exists.
    const cSql = `SELECT COUNT(*) AS n FROM gpr_legacy_stock WHERE movement_type='legacy_seed'`;
    const c = pgPool ? (await pgPool.query(cSql)).rows[0] : db.prepare(cSql).get();
    if (Number((c && c.n) || 0) === 0) {
      const seedRows = [
        { location: 'FIRST FLOOR (MC ROOM 17,18,19)', qty_kg: 7782.00, floor: '1F' },
        { location: 'OM SHANTI ROOM',                 qty_kg: 32909.00, floor: null },
        { location: 'GROUND FLOOR MAZENINE',          qty_kg: 200.00,  floor: 'GF' },
      ];
      for (const r of seedRows) {
        await gprLegacyMove({ movement_type: 'legacy_seed', account: 'cutting', location: r.location,
          floor: r.floor, qty_kg: r.qty_kg, note: 'legacy opening stock (Shri Kant Gupta, 19 Sep 2026)', moved_by: 'v55V-seed' });
      }
      logAudit('v55V-seed', 'system', 'gpr', 'GPR_LEGACY_IMPORT', '3 location(s), 40891.0kg (boot seed)', null);
      console.log('[v55V GPR] legacy cutting stock seeded — 3 locations, 40,891 kg');
    }
  } catch (e) { console.warn('[v55V GPR] seed upgrade skipped:', e?.message); }
}

// v55A masters upgrade (see boot-chain comment). Safe on every boot.
async function _gprUpgradeMastersV55A() {
  const get1 = async (key) => {
    const sql = `SELECT value_json FROM gpr_masters WHERE master_key=${pgPool ? '$1' : '?'}`;
    const r = pgPool ? (await pgPool.query(sql, [key])).rows[0] : db.prepare(sql).get(key);
    return r ? JSON.parse(r.value_json) : null;
  };
  const put1 = async (key, val) => {
    if (pgPool) await pgPool.query(`INSERT INTO gpr_masters (master_key, value_json, updated_by) VALUES ($1,$2,'v55A-upgrade')
      ON CONFLICT(master_key) DO UPDATE SET value_json=$2, updated_by='v55A-upgrade', updated_at=NOW()::TEXT`, [key, JSON.stringify(val)]);
    else db.prepare(`INSERT INTO gpr_masters (master_key, value_json, updated_by) VALUES (?,?,'v55A-upgrade')
      ON CONFLICT(master_key) DO UPDATE SET value_json=excluded.value_json, updated_by='v55A-upgrade', updated_at=datetime('now')`).run(key, JSON.stringify(val));
  };
  try {
    if (!(await get1('mmt_chemicals'))) await put1('mmt_chemicals', GPR_SEED_MASTERS.mmt_chemicals);
    if (!(await get1('cutting_colour_codes'))) await put1('cutting_colour_codes', []);   // v55K item 12 architecture
    // v56U: constants added in a later build reach an already-seeded store — FILL-IF-ABSENT only, a
    // value the plant has tuned is never overwritten. Makes the new keys visible/editable in Masters.
    const gc = await get1('gpr_constants');
    if (gc && typeof gc === 'object') {
      const add = Object.keys(GPR_SEED_MASTERS.gpr_constants).filter(k => !(k in gc));
      if (add.length) {
        add.forEach(k => { gc[k] = GPR_SEED_MASTERS.gpr_constants[k]; });
        await put1('gpr_constants', gc);
        console.log('[v56U GPR] gpr_constants gained ' + add.join(', '));
      }
    }
    const cols = await get1('colourants');
    if (Array.isArray(cols) && cols.length && typeof cols[0] === 'string') {
      const byName = {}; GPR_SEED_MASTERS.colourants.forEach(c => { byName[c.name.toLowerCase()] = c.code; });
      await put1('colourants', cols.map(n => ({ code: byName[String(n).toLowerCase()] || '', name: n })));
      console.log('[v55A GPR] colourants master migrated to coded form');
    }
  } catch (e) { console.warn('[v55A GPR] masters upgrade skipped:', e?.message); }
}

